CREATE TABLE orchestration_control_policy_revisions(orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,revision INTEGER NOT NULL CHECK(revision>0),remote_allowed INTEGER NOT NULL CHECK(remote_allowed IN(0,1)),prefer_local INTEGER NOT NULL CHECK(prefer_local IN(0,1)),reasoning_profile TEXT NOT NULL CHECK(reasoning_profile IN('fast','balanced','deep','maximum')),created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(orchestration_id,revision))STRICT;
CREATE TABLE orchestration_input_sources(orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES context_sources(source_id)ON DELETE RESTRICT,created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(orchestration_id,source_id))STRICT;
CREATE TABLE planner_invocations(invocation_id TEXT PRIMARY KEY,orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,workspace_id TEXT NOT NULL REFERENCES workspaces(id)ON DELETE RESTRICT,prompt_digest TEXT NOT NULL CHECK(length(prompt_digest)=64 AND prompt_digest NOT GLOB '*[^0-9a-f]*'),proposal_json TEXT NOT NULL CHECK(json_valid(proposal_json)),created_at INTEGER NOT NULL CHECK(created_at>=0))STRICT;
CREATE TABLE orchestration_control_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT NOT NULL REFERENCES workspaces(id)ON DELETE RESTRICT,orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,kind TEXT NOT NULL,payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),created_at INTEGER NOT NULL CHECK(created_at>=0))STRICT;
CREATE INDEX orchestration_control_events_replay_idx ON orchestration_control_events(workspace_id,orchestration_id,sequence);
CREATE TRIGGER ce_graph AFTER INSERT ON orchestration_graph_revisions BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'graph.revised',json_object('revision',NEW.revision,'digest',NEW.graph_digest),NEW.created_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
CREATE TRIGGER ce_task AFTER INSERT ON orchestration_task_state_revisions BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'task.state',json_object('task',NEW.task_node_id,'state',NEW.state,'revision',NEW.state_revision,'attempts',NEW.attempt_count),NEW.created_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
CREATE TRIGGER ce_worker_i AFTER INSERT ON worker_attempts BEGIN INSERT INTO orchestration_control_events VALUES(NULL,NEW.workspace_id,NEW.orchestration_id,'worker.reserved',json_object('attempt',NEW.attempt_id,'task',NEW.task_node_id,'provider',NEW.provider_id,'profile',NEW.profile_id),NEW.created_at);END;
CREATE TRIGGER ce_worker_u AFTER UPDATE OF state ON worker_attempts WHEN OLD.state<>NEW.state BEGIN INSERT INTO orchestration_control_events VALUES(NULL,NEW.workspace_id,NEW.orchestration_id,'worker.state',json_object('attempt',NEW.attempt_id,'task',NEW.task_node_id,'state',NEW.state,'diagnostic',NEW.diagnostic),COALESCE(NEW.completed_at,NEW.started_at,NEW.created_at));END;
CREATE TRIGGER ce_route AFTER INSERT ON routing_decisions BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'routing.selected',json_object('decision',NEW.decision_id,'task',NEW.task_node_id,'provider',NEW.provider_id,'profile',NEW.profile_id),NEW.created_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
CREATE TRIGGER ce_artifact AFTER INSERT ON worker_artifacts BEGIN INSERT INTO orchestration_control_events VALUES(NULL,NEW.workspace_id,NEW.orchestration_id,'artifact.created',json_object('artifact',NEW.artifact_id,'task',NEW.task_node_id,'kind',NEW.artifact_kind,'sha256',NEW.content_hash),NEW.created_at);END;
CREATE TRIGGER ce_retry AFTER INSERT ON worker_retry_decisions BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'retry.decided',json_object('decision',NEW.decision_id,'task',NEW.task_node_id,'mode',NEW.mode,'allowed',NEW.allowed),NEW.created_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
CREATE TRIGGER ce_budget AFTER INSERT ON orchestration_budget_revisions BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'budget.revised',json_object('revision',NEW.revision,'cost',NEW.max_remote_cost_micros,'workers',NEW.max_concurrent_workers),NEW.created_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
CREATE TRIGGER ce_cancel AFTER INSERT ON orchestration_cancellations BEGIN INSERT INTO orchestration_control_events SELECT NULL,o.workspace_id,NEW.orchestration_id,'orchestration.cancelled',json_object('by',NEW.requested_by_subject),NEW.requested_at FROM orchestrations o WHERE o.orchestration_id=NEW.orchestration_id;END;
